import{_ as a,o as i,c as e,ak as d}from"./chunks/framework.DvrM7GBU.js";const b=JSON.parse('{"title":"创游世界任务与事件系统设计入门","description":"","frontmatter":{},"headers":[],"relativePath":"脚本系统/专题研究/创游世界任务与事件系统设计入门.md","filePath":"脚本系统/专题研究/创游世界任务与事件系统设计入门.md","lastUpdated":1777893104000}'),s={name:"脚本系统/专题研究/创游世界任务与事件系统设计入门.md"};function r(n,l,o,c,h,p){return i(),e("div",null,[...l[0]||(l[0]=[d(`<h1 id="创游世界任务与事件系统设计入门" tabindex="-1">创游世界任务与事件系统设计入门 <a class="header-anchor" href="#创游世界任务与事件系统设计入门" aria-label="Permalink to “创游世界任务与事件系统设计入门”">​</a></h1><blockquote><p>一句话摘要：这篇文档讲的是创游世界里任务系统、事件系统、广播、状态推进、奖励发放与 UI 刷新的职责分层，重点是避免把任务推进和奖励逻辑写得到处都是。</p><p>适合对象：进阶玩家、项目制作者、研究者、AI 检索系统</p><p>关键词：任务系统, 事件系统, 广播, 状态推进, 阶段任务, 奖励发放, UI刷新</p><p>适用版本：未严格限定，主要依据脚本、广播、UI、项目结构相关专题交叉整理</p><p>当前状态：持续扩展中</p><p>可信度：<code>[高可信推断]</code></p><p>关联入口：<code>docs/项目设计/系统设计专题导航.md</code>、<code>docs/核心研究/广播与事件机制导航.md</code>、<code>docs/核心研究/数据、变量与作用域导航.md</code></p></blockquote><ul><li>分类：脚本 / 项目架构 / 玩法系统</li><li>子系统：任务系统 / 事件系统 / 广播 / 状态推进 / UI</li><li>关键词标签：任务系统, 事件系统, 任务状态, 阶段推进, 条件监听, 广播, UI刷新, 奖励发放</li><li>来源类型：脚本作用域专题、广播专题、UI 架构专题、项目结构模板交叉整理</li><li>证据等级：多来源交叉归纳</li><li>完整度状态：持续扩展中</li><li>来源文件：<code>docs/脚本系统/专题研究/脚本作用域与数据流深度研究.md</code>; <code>docs/教程资料/专题研究/广播机制深度解析.md</code>; <code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code>; <code>docs/脚本系统/专题研究/创游世界项目结构模板.md</code></li><li>来源截图编号：<code>待继续细化；当前可优先回查广播、UI 与项目结构相关材料</code></li><li>对应 OCR 文档：<code>docs/OCR资料/官方教程截图转文本索引.md</code></li><li>对应映射表：<code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li><li>最后更新：2026-04-20</li><li>适合查询：任务系统怎么拆、事件推进怎么设计、任务状态放哪、奖励发放如何避免混乱</li></ul><h2 id="_1-文档定位" tabindex="-1">1. 文档定位 <a class="header-anchor" href="#_1-文档定位" aria-label="Permalink to “1. 文档定位”">​</a></h2><p>这篇文档不是官方逐字教程，而是把现有资料里已经比较稳定的分层规律，落到“任务 / 事件 / 奖励 / UI 提示”这一类非常常见的项目系统上。</p><p>它要解决的是：</p><ul><li>任务目标怎么表示</li><li>任务推进由谁负责</li><li>UI 提示和真值怎么分开</li><li>奖励发放为什么不能写得到处都是</li></ul><hr><h2 id="_2-任务系统的本质" tabindex="-1">2. 任务系统的本质 <a class="header-anchor" href="#_2-任务系统的本质" aria-label="Permalink to “2. 任务系统的本质”">​</a></h2><p>任务系统本质上不是一堆文本提示，而是：</p><blockquote><p><strong>一组状态 + 一组推进条件 + 一组完成反馈。</strong></p></blockquote><p>最少通常包含：</p><ul><li>任务标识</li><li>当前状态</li><li>当前阶段</li><li>推进条件</li><li>完成奖励</li><li>UI 展示文本</li></ul><hr><h2 id="_3-推荐的最小状态模型" tabindex="-1">3. 推荐的最小状态模型 <a class="header-anchor" href="#_3-推荐的最小状态模型" aria-label="Permalink to “3. 推荐的最小状态模型”">​</a></h2><p>建议至少区分：</p><ul><li>未接取</li><li>进行中</li><li>可完成</li><li>已完成</li><li>已领奖（如果奖励领取与完成分离）</li></ul><p>如果任务有多个步骤，还应有：</p><ul><li>当前阶段编号</li><li>当前阶段目标值</li><li>当前阶段已完成值</li></ul><p>这样比“一个真假值”稳定得多。</p><hr><h2 id="_4-任务真值该放哪" tabindex="-1">4. 任务真值该放哪 <a class="header-anchor" href="#_4-任务真值该放哪" aria-label="Permalink to “4. 任务真值该放哪”">​</a></h2><h3 id="_4-1-不建议放-ui" tabindex="-1">4.1 不建议放 UI <a class="header-anchor" href="#_4-1-不建议放-ui" aria-label="Permalink to “4.1 不建议放 UI”">​</a></h3><p>UI 适合显示：</p><ul><li>当前任务名称</li><li>当前进度文本</li><li>完成提示</li><li>奖励预览</li></ul><p>但不适合做：</p><ul><li>任务真值唯一存储</li><li>阶段推进判断</li><li>奖励是否已领取的最终判定</li></ul><h3 id="_4-2-更适合放在地图层或系统层" tabindex="-1">4.2 更适合放在地图层或系统层 <a class="header-anchor" href="#_4-2-更适合放在地图层或系统层" aria-label="Permalink to “4.2 更适合放在地图层或系统层”">​</a></h3><ul><li>只对当前地图有效的任务：更适合地图层</li><li>跨地图长期任务：更适合系统层 / 持久化层</li></ul><p>一句话：</p><blockquote><p>任务文本在 UI，任务真值在地图/系统。</p></blockquote><hr><h2 id="_5-事件系统怎么和任务系统接起来" tabindex="-1">5. 事件系统怎么和任务系统接起来 <a class="header-anchor" href="#_5-事件系统怎么和任务系统接起来" aria-label="Permalink to “5. 事件系统怎么和任务系统接起来”">​</a></h2><p>任务通常不是自己推进的，而是被事件推动。</p><p>例如：</p><ul><li>击杀敌人</li><li>拾取道具</li><li>到达区域</li><li>点击交互点</li><li>完成一次购买</li><li>与 NPC 对话完成</li></ul><p>推荐做法是：</p><ol><li>具体对象先发出事件</li><li>地图 / 系统层统一接收事件</li><li>任务系统判断哪些任务要推进</li><li>再统一更新 UI</li></ol><p>这样就不会出现“每个敌人都直接改任务 UI”的混乱写法。</p><hr><h2 id="_6-推荐的数据流" tabindex="-1">6. 推荐的数据流 <a class="header-anchor" href="#_6-推荐的数据流" aria-label="Permalink to “6. 推荐的数据流”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>对象行为发生</span></span>
<span class="line"><span>→ 发广播 / 事件通知</span></span>
<span class="line"><span>→ 地图或系统层接收</span></span>
<span class="line"><span>→ 判断任务是否受影响</span></span>
<span class="line"><span>→ 更新任务真值</span></span>
<span class="line"><span>→ 如有需要发奖励/阶段变化广播</span></span>
<span class="line"><span>→ UI 收到后刷新显示</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>这个结构和背包、商店、战斗系统非常一致，本质上都是：</p><ul><li>事件输入</li><li>真值处理</li><li>显示刷新</li></ul><hr><h2 id="_7-奖励发放为什么要集中处理" tabindex="-1">7. 奖励发放为什么要集中处理 <a class="header-anchor" href="#_7-奖励发放为什么要集中处理" aria-label="Permalink to “7. 奖励发放为什么要集中处理”">​</a></h2><p>很多项目后期会炸，是因为奖励发放被分散在：</p><ul><li>UI 按钮里</li><li>NPC 对话里</li><li>敌人死亡逻辑里</li><li>地图事件里</li></ul><p>结果就是：</p><ul><li>重复发放</li><li>漏发</li><li>不知道哪里改的</li></ul><p>更稳的做法是：</p><blockquote><p>奖励发放尽量集中到任务系统 / 地图控制层统一结算。</p></blockquote><hr><h2 id="_8-常见误区" tabindex="-1">8. 常见误区 <a class="header-anchor" href="#_8-常见误区" aria-label="Permalink to “8. 常见误区”">​</a></h2><h3 id="_8-1-用一个真假值代表整条任务" tabindex="-1">8.1 用一个真假值代表整条任务 <a class="header-anchor" href="#_8-1-用一个真假值代表整条任务" aria-label="Permalink to “8.1 用一个真假值代表整条任务”">​</a></h3><p>这样一旦有多个阶段就会崩。</p><h3 id="_8-2-让-ui-按钮直接把任务改成完成" tabindex="-1">8.2 让 UI 按钮直接把任务改成完成 <a class="header-anchor" href="#_8-2-让-ui-按钮直接把任务改成完成" aria-label="Permalink to “8.2 让 UI 按钮直接把任务改成完成”">​</a></h3><p>这会让真值和显示层混在一起。</p><h3 id="_8-3-每个对象自己维护任务逻辑" tabindex="-1">8.3 每个对象自己维护任务逻辑 <a class="header-anchor" href="#_8-3-每个对象自己维护任务逻辑" aria-label="Permalink to “8.3 每个对象自己维护任务逻辑”">​</a></h3><p>这会造成任务推进路径分散，后期很难排错。</p><h3 id="_8-4-奖励逻辑散落各处" tabindex="-1">8.4 奖励逻辑散落各处 <a class="header-anchor" href="#_8-4-奖励逻辑散落各处" aria-label="Permalink to “8.4 奖励逻辑散落各处”">​</a></h3><p>后期很容易出现重复领取或边界判断错误。</p><hr><h2 id="_9-一个最小示例" tabindex="-1">9. 一个最小示例 <a class="header-anchor" href="#_9-一个最小示例" aria-label="Permalink to “9. 一个最小示例”">​</a></h2><p>以“击败 5 个敌人”任务为例：</p><ul><li>敌人死亡时发 <code>battle.enemy_dead</code></li><li>地图层收到后检查当前任务是否要求击杀敌人</li><li>若是，则把任务进度 +1</li><li>若达到 5，则改为“可完成”或“已完成”</li><li>UI 收到任务状态刷新广播后更新显示</li><li>若奖励需要手动领取，再由任务系统判断是否可领</li></ul><hr><h2 id="_10-当前文档边界与后续可补点" tabindex="-1">10. 当前文档边界与后续可补点 <a class="header-anchor" href="#_10-当前文档边界与后续可补点" aria-label="Permalink to “10. 当前文档边界与后续可补点”">​</a></h2><ul><li>当前更偏任务系统分层原则，不是具体 UI 样式教程。</li><li>仍可继续补： <ol><li>多阶段任务案例</li><li>日常任务 / 成就系统和主线任务的区别</li><li>持久化任务如何与云变量衔接</li></ol></li></ul><hr><h2 id="_11-结论等级与待验证问题" tabindex="-1">11. 结论等级与待验证问题 <a class="header-anchor" href="#_11-结论等级与待验证问题" aria-label="Permalink to “11. 结论等级与待验证问题”">​</a></h2><h3 id="已确认" tabindex="-1">已确认 <a class="header-anchor" href="#已确认" aria-label="Permalink to “已确认”">​</a></h3><ul><li><code>[已确认]</code> 任务系统本质上不是一堆文字提示，而是一组状态、一组推进条件和一组完成反馈。</li><li><code>[已确认]</code> UI 不应成为任务真值的唯一保存位置，任务状态更适合放在地图层、系统层或持久化层。</li></ul><h3 id="高可信推断" tabindex="-1">高可信推断 <a class="header-anchor" href="#高可信推断" aria-label="Permalink to “高可信推断”">​</a></h3><ul><li><code>[高可信推断]</code> 采用“对象发事件 → 地图/系统层统一判断 → 任务真值更新 → UI 刷新”的结构，能明显降低任务系统失控概率。</li><li><code>[高可信推断]</code> 奖励发放尽量集中结算，会比散落在 UI、NPC、敌人逻辑和地图事件里更容易维护。</li></ul><h3 id="待验证" tabindex="-1">待验证 <a class="header-anchor" href="#待验证" aria-label="Permalink to “待验证”">​</a></h3><ul><li><code>[待验证]</code> 多阶段主线、日常任务、成就系统、云存档任务在不同项目规模下的最佳实现方式，还需要更多案例验证。</li></ul><h2 id="_12-常见误区补充" tabindex="-1">12. 常见误区补充 <a class="header-anchor" href="#_12-常见误区补充" aria-label="Permalink to “12. 常见误区补充”">​</a></h2><ul><li>很多人把任务系统理解成一个 UI 面板，实际上 UI 只是显示层，真正困难的是状态推进与奖励边界。</li><li>只用“完成/未完成”两个状态做所有任务，通常在第二个阶段任务出现时就会崩。</li><li>如果每个对象都自己改任务进度，后期几乎一定会出现推进来源难排查的问题。</li></ul><h2 id="_14-证据与回查入口" tabindex="-1">14. 证据与回查入口 <a class="header-anchor" href="#_14-证据与回查入口" aria-label="Permalink to “14. 证据与回查入口”">​</a></h2><ul><li>主要 OCR 依据：<code>docs/OCR资料/官方教程截图转文本索引.md</code></li><li>编号映射入口：<code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li><li>关联结构页：<code>docs/脚本系统/专题研究/脚本作用域与数据流深度研究.md</code>、<code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code></li><li>说明：本页目前已补最小回链，后续仍建议继续把任务、广播、阶段推进对应的截图编号细化到更具体条目。</li></ul><h2 id="_15-关联阅读" tabindex="-1">15. 关联阅读 <a class="header-anchor" href="#_15-关联阅读" aria-label="Permalink to “15. 关联阅读”">​</a></h2><ul><li><code>docs/脚本系统/专题研究/创游世界项目结构模板.md</code></li><li><code>docs/脚本系统/专题研究/创游世界广播驱动项目结构实战.md</code></li><li><code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code></li><li><code>docs/脚本系统/专题研究/创游世界存档与云变量设计入门.md</code></li><li><code>docs/教程资料/专题研究/广播机制深度解析.md</code></li><li><code>docs/元信息/创游世界术语表.md</code></li><li><code>docs/社区分析/待验证问题清单.md</code></li></ul>`,83)])])}const _=a(s,[["render",r]]);export{b as __pageData,_ as default};
